/**
 * jev-pet — Jev as a companion above the prompt, at the right: Claude the
 * pilot (Claude Code's character in pilot gear), with a speech bubble saying what Jev just
 * decided, so the decisions stay out of the conversation. It also owns
 * `/jev`, the switches for every part of jev-pilot.
 *
 * While a turn runs the pilot shows what Claude is doing, and the bubble says
 * it beside a spinner: thinking (a thought cloud), reading (a book),
 * searching (a magnifier), writing (paper and a pencil), running a command
 * (a terminal), anything else (a subagent) flying, goggles down. With
 * subagents still working in the background after a turn, it cruises,
 * goggles down, until they finish; at max effort the goggles stay down for
 * the turn. Idle, it hovers, its scarf's end dipping every few seconds; it
 * blinks, and every few seconds plays for a moment: jumps rope, waves, looks
 * around. Resting, it redraws only when something moves.
 *
 * The router and the skill module set what it says (pet-art.ts `say`) and ask
 * for a redraw; this module draws it, in the `AbovePrompt` band on the
 * terminal. Nothing draws in `claude -p`, the desktop app or mobile.
 */
import type { Register, Timer } from 'claude-code'
import {
  describeFeatures,
  feature,
  FEATURE_INFO,
  featureOverrides,
  loadFeatureOverrides,
  parseJevCommand,
  setFeature,
} from './features.ts'
import { applyCrewCommand, describeChoice, describeCrew, describeSlot, MAX_MODELS, MODELS_PAGE, parseCrewCommand, resolveCodexChoice, resolveModel, resolveOpencodeChoice, slotAlias, type CrewCommand, type ReviewerResolved } from './crew.ts'
import { resetBriefing } from './summary.ts'
import { describeStats } from './session-stats.ts'
import { entriesOf, LEDGER_KEY } from './ledger.ts'
import { applied, currentTuning, describeTuning, proposals, setTuning, TUNING_KEY, tuningLoaded, tuningOf } from './tuning.ts'
import { codexModels, crew, crewOverrides, describeHealth, router, setCrewOverrides } from './crew-state.ts'
import { CREW_KEY, checkCrew, checkSlot, ensureCrew, modelCatalog, opencodeModels, publishSlots, refreshCodexModels, registerCrew, type CrewIo } from './crew-run.ts'
import {
  type Act,
  ACT_LABEL,
  actOfTool,
  CANVAS_W,
  currentSpeech,
  isBoosted,
  MOOD_COLOR,
  PLAY_FRAMES,
  PLAYS,
  sceneRows,
  setBoost,
  WORK_ACTS,
} from './pet-art.ts'

const FEATURES_KEY = 'features'
const FLY_MS = 200
// Background subagents still working, no turn running: the pilot cruises,
// goggles down, at a calmer rate; running agents are checked this often.
const CRUISE_MS = 450
const AGENTS_EVERY_MS = 1500
const BLINK_EVERY_MS = 4600
const BLINK_MS = 170
const PLAY_EVERY_MS = 9000
const PLAY_STEP_MS = 180
/** How many loops each idle play runs for: about three seconds each. */
const PLAY_LOOPS = { rope: 4, wave: 4, look: 2 } as const
const SPINNER = '⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏'

export const register: Register = (on, options) => {
  let act: Act = 'rest'
  let frame = 0
  let blink = false
  let workingTurn: string | null = null
  let flying: Timer | null = null
  let blinker: Timer | null = null
  let player: Timer | null = null
  let playing: Timer | null = null
  let plays = 0
  let cruising: Timer | null = null
  let watcher: Timer | null = null
  // The main loop's tool calls in flight, each with the act it shows.
  const running = new Map<string, Act>()
  let calls = 0

  const stopPlay = () => {
    playing?.cancel()
    playing = null
  }
  const stopCruise = () => {
    cruising?.cancel()
    cruising = null
  }

  // Session setup: the saved switches, the /jev command, the blink. (Under a
  // match-all matcher: the router hooks session.start too, one unmatched
  // registration per plugin.)
  on('session.start', { cwd: /(?:)/ }, async ($, e, next) => {
    const result = await next(e)
    loadFeatureOverrides(await $.store.get(FEATURES_KEY).catch(() => undefined))
    await $.command
      .register({
        name: 'jev',
        description: 'jev-pilot switches: /jev shows them, /jev <effort|raise|subagents|skills|strategy|model|pet> on|off',
        argumentHint: '[<feature> on|off | all on|off | reset]',
        immediate: true,
      })
      .catch((error) => $.ui.log(`[jev-pilot] /jev not registered: ${String(error)}`))
    blinker?.cancel()
    blinker = $.clock.every(BLINK_EVERY_MS, () => {
      if (!feature('pet') || workingTurn || playing || cruising) return
      blink = true
      $.ui.invalidate('ui.render')
      $.clock.after(BLINK_MS, () => {
        blink = false
        $.ui.invalidate('ui.render')
      })
    })
    // Idle play: every few seconds one of the plays, in turn, for a moment.
    player?.cancel()
    player = $.clock.every(PLAY_EVERY_MS, () => {
      if (!feature('pet') || workingTurn || playing || cruising) return
      const play = PLAYS[plays++ % PLAYS.length] as (typeof PLAYS)[number]
      const steps = PLAY_FRAMES[play] * PLAY_LOOPS[play]
      act = play
      frame = 0
      playing = $.clock.every(PLAY_STEP_MS, () => {
        frame++
        if (frame >= steps) {
          stopPlay()
          act = 'rest'
          frame = 0
        }
        $.ui.invalidate('ui.render')
      })
      $.ui.invalidate('ui.render')
    })
    // Subagents working in the background, with no turn running: the pilot
    // cruises until they are all done. Asked of the engine every few seconds,
    // so one that was stopped or failed never leaves it flying.
    watcher?.cancel()
    watcher = $.clock.every(AGENTS_EVERY_MS, async () => {
      if (!feature('pet')) return
      let busy = false
      try {
        busy = (await $.agent.list()).some((agent) => agent.status === 'running')
      } catch {
        busy = false
      }
      if (busy && !workingTurn && !cruising) {
        stopPlay()
        act = 'fly'
        frame = 0
        cruising = $.clock.every(CRUISE_MS, () => {
          frame++
          $.ui.invalidate('ui.render')
        })
      } else if (!busy && cruising) {
        stopCruise()
        if (!workingTurn) {
          act = 'rest'
          frame = 0
          $.ui.invalidate('ui.render')
        }
      }
    })
    return result
  })

  // A new session in this worker (/clear, resume): the old timers stop.
  on('session.end', { reason: /(?:)/ }, async ($, e, next) => {
    flying?.cancel()
    flying = null
    stopPlay()
    stopCruise()
    setBoost(false)
    act = 'rest'
    workingTurn = null
    running.clear()
    return next(e)
  })

  on('command.run', { command: 'jev' }, async ($, e) => {
    // `/jev tune [apply|reset]`: the changes the ledger suggests.
    const tune = /^\s*tune(?:\s+(apply|reset))?\s*$/i.exec(e.args)
    if (tune) {
      if (!tuningLoaded()) setTuning(tuningOf(await $.store.get(TUNING_KEY).catch(() => undefined)))
      const entries = entriesOf(await $.store.get(LEDGER_KEY).catch(() => undefined))
      const action = tune[1]?.toLowerCase()
      if (action === 'reset') {
        setTuning({ values: {}, since: Date.now() })
        await $.store.delete(TUNING_KEY).catch(() => undefined)
        return { text: `tuning cleared; back to your settings.\n\n${describeTuning(entries)}` }
      }
      if (action === 'apply') {
        const found = proposals(entries)
        if (found.length === 0) return { text: `nothing to apply.\n\n${describeTuning(entries)}` }
        const next = applied(currentTuning(), found, Date.now())
        setTuning(next)
        await $.store.set(TUNING_KEY, next).catch((error) => $.ui.log(`[jev-pilot] tuning not saved: ${String(error)}`))
        return {
          text: `applied ${found.map((f) => `${f.option} ${f.from} → ${f.to}`).join(', ')}. The next suggestion waits for 20 new turns.\n\n${describeTuning(entries)}`,
        }
      }
      return { text: describeTuning(entries) }
    }
    // The crew: `/jev status`, `/jev mode ...`, `/jev alpha <model>|off`,
    // `/jev junior <slot>`, `/jev reviewer <codex|opencode>`.
    const crewCommand = /^\s*status\s*$/i.test(e.args) ? ({ kind: 'show' } as const) : parseCrewCommand(e.args)
    if (crewCommand) {
      const crewIo: CrewIo = {
        fetch: (url, init) => $.http.fetch(url, init),
        home: () => $.env.get('HOME'),
        routerUrl: () => $.env.get('JEV_ROUTER_URL'),
        write: (path, text) => $.fs.write(path, text),
        read: async (path) => ((await $.fs.exists(path)) ? $.fs.read(path) : null),
        run: (argv, timeoutMs) => $.process.run(argv, { timeoutMs }),
        storeGet: (key) => $.store.get(key),
        sleep: (ms) => $.clock.sleep(ms),
        register: async (spec) => {
          await $.agent.register(spec)
        },
      }
      const openrouterKey = typeof options.openrouterApiKey === 'string' && options.openrouterApiKey ? options.openrouterApiKey : null
      await ensureCrew(crewIo, openrouterKey)
      if (crewCommand.kind === 'unknown') return { text: `jev-pilot: unknown "${crewCommand.text}".\n${describeCrew(crew(), router() !== null, codexModels())}` }
      if (crewCommand.kind === 'show') {
        await checkCrew(crewIo, openrouterKey)
        await registerCrew(crewIo)
        return { text: `${describeCrew(crew(), router() !== null, codexModels())}\n${describeHealth()}\n\n${describeStats()}` }
      }
      if (crewCommand.kind === 'slot') return { text: describeSlot(crew(), crewCommand.slot, crewOverrides().recent ?? []) }
      // What was pasted, checked against OpenRouter's list before it's set.
      let change: CrewCommand = crewCommand
      let about: string | null = null
      // A reviewer's model and effort, checked against the CLI's own list before it's set.
      if (crewCommand.kind === 'reviewer-paste') {
        const current = crew().reviewerChoices[crewCommand.reviewer] ?? {}
        let resolved: ReviewerResolved
        if (crewCommand.reviewer === 'codex') {
          if (codexModels().length === 0) await refreshCodexModels(crewIo)
          resolved = resolveCodexChoice(crewCommand.input, crewCommand.effort, codexModels(), current)
        } else {
          resolved = resolveOpencodeChoice(crewCommand.input, crewCommand.effort, crewCommand.input ? await opencodeModels(crewIo) : [], current)
        }
        if (!resolved.ok) {
          const list = resolved.suggestions.length > 0 ? `\nAvailable:\n${resolved.suggestions.map((line) => `  ${line}`).join('\n')}` : ''
          return { text: `The ${crewCommand.reviewer} reviewer is not changed: ${resolved.why}.${list}` }
        }
        change = { kind: 'reviewer-choice', reviewer: crewCommand.reviewer, choice: resolved.choice }
        about = resolved.about || null
      }
      if (crewCommand.kind === 'paste') {
        const resolved = resolveModel(crewCommand.input, await modelCatalog(crewIo))
        if (!resolved.ok) {
          const tries = resolved.suggestions.length > 0 ? `\nDid you mean:\n${resolved.suggestions.map((id) => `  /jev ${crewCommand.slot} ${id}`).join('\n')}` : ''
          return { text: `${crewCommand.slot} not changed: ${resolved.why}.${tries}\nFind one at ${MODELS_PAGE} and paste its id, link or name.` }
        }
        // A new name past the limit: each custom model is an option Jev weighs.
        if (!crew().slots.some((slot) => slot.name === crewCommand.slot) && crew().slots.length >= MAX_MODELS) {
          return { text: `${crewCommand.slot} not added: ${MAX_MODELS} custom models is the most at once. Remove one first: /jev remove <name>` }
        }
        change = { kind: 'model', slot: crewCommand.slot, model: resolved.id, about: resolved.about }
        about = resolved.about
      }
      if (change.kind === 'model' && !change.model && !crew().slots.some((slot) => slot.name === change.slot)) {
        return { text: `No custom model is called ${change.slot}.\n\n${describeCrew(crew(), router() !== null, codexModels())}` }
      }
      setCrewOverrides(applyCrewCommand(crewOverrides(), change))
      await $.store.set(CREW_KEY, crewOverrides()).catch((error) => $.ui.log(`[jev-pilot] crew not saved: ${String(error)}`))
      await publishSlots(crewIo).catch((error) => $.ui.log(`[jev-pilot] custom models not published: ${String(error)}`))
      if (change.kind === 'model' && change.model) await checkSlot(crewIo, openrouterKey, change.slot, change.model)
      // A new junior, say: its agent type from the next turn, and the model
      // told about the change with its next prompt.
      await registerCrew(crewIo)
      resetBriefing()
      const headline =
        change.kind === 'model'
          ? change.model
            ? `${change.slot} is now ${change.model}${about ? ` (${about})` : ''}. Saved for every session.\n` +
              `It's in /model from your next claude-jev session (press s there to use it for that session only). To use it as the main model right now: /model ${slotAlias(change.slot)}. That also makes it your default for new sessions, and /model default undoes that.\n\n`
            : `${change.slot} is removed, from every session and from /model.\n\n`
          : change.kind === 'reviewer-choice'
            ? `${change.reviewer} reviews now run on ${describeChoice(change.choice, codexModels())}${about ? ` (${about})` : ''}. Saved for every session. To use another model for one review, just say so ("review it with codex, luna, high").\n\n`
            : ''
      // A mode that hands work to custom models, with none set: say how to set one.
      const unset =
        change.kind === 'mode' && (change.mode === 'budget' || change.mode === 'junior-lead') && crew().slots.length === 0
          ? `\n\nNo custom model is set yet, so this mode has nothing to hand work to. Add one from ${MODELS_PAGE}:\n  /jev <name you choose> <model>`
          : ''
      return { text: `${headline}${describeCrew(crew(), router() !== null, codexModels())}\n${describeHealth()}${unset}` }
    }
    const command = parseJevCommand(e.args)
    if (command.kind === 'unknown') {
      return { text: `jev-pilot: unknown "${command.text}".\n${describeFeatures()}` }
    }
    if (command.kind === 'reset') loadFeatureOverrides({})
    if (command.kind === 'set') for (const name of command.features) setFeature(name, command.on)
    if (command.kind !== 'status') {
      await $.store.set(FEATURES_KEY, featureOverrides()).catch((error) => $.ui.log(`[jev-pilot] switches not saved: ${String(error)}`))
      $.ui.invalidate('ui.render')
    }
    if (command.kind === 'set' && command.features.length === 1) {
      const name = command.features[0] as keyof typeof FEATURE_INFO
      return { text: `jev-pilot: ${name} ${command.on ? 'on' : 'off'} (${FEATURE_INFO[name]}) · /jev ${name} ${command.on ? 'off' : 'on'} undoes it` }
    }
    return { text: `${describeFeatures()}\n\n${describeStats()}` }
  })

  // While a turn runs, the pilot shows what Claude is doing: thinking first.
  on('turn.start', async ($, e, next) => {
    const result = await next(e)
    workingTurn = e.turnId
    flying?.cancel()
    stopPlay()
    stopCruise()
    setBoost(false)
    running.clear()
    act = 'think'
    frame = 0
    flying = $.clock.every(FLY_MS, () => {
      if (!feature('pet')) return
      frame++
      $.ui.invalidate('ui.render')
    })
    return result
  })

  // The model's response as it streams: thinking shows as thinking, the
  // answer's text as writing. Observed only: every chunk passes on as it came.
  on('turn.step', { turnId: /(?:)/ }, async function* ($, e, next) {
    if (e.agentId || e.turnId !== workingTurn) return yield* next(e)
    if (running.size === 0) act = 'think'
    for await (const chunk of next(e)) {
      if (running.size === 0) {
        if (chunk.kind === 'thinking') act = 'think'
        else if (chunk.kind === 'text') act = 'write'
      }
      yield chunk
    }
  })

  // A main-loop tool call shows what the tool does: reading, searching,
  // editing, running a command; anything else (a subagent) flies. When it is
  // done, the next call still running shows, or thinking.
  on('tool.call', { tool: /(?:)/ }, async ($, e, next) => {
    if (e.agentId || !workingTurn) return next(e)
    const id = e.tool_use_id ?? `call-${++calls}`
    act = actOfTool(e.tool)
    running.set(id, act)
    try {
      return await next(e)
    } finally {
      running.delete(id)
      if (workingTurn) act = [...running.values()].at(-1) ?? 'think'
    }
  })

  on('turn.complete', { turnId: /(?:)/ }, async ($, e, next) => {
    const result = await next(e)
    if (e.turnId === workingTurn) {
      running.clear()
      workingTurn = null
      flying?.cancel()
      flying = null
      setBoost(false)
      act = 'rest'
      frame = 0
      $.ui.invalidate('ui.render')
    }
    return result
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (!feature('pet') || e.props.hasSurvey || e.surface !== 'terminal') return next(e)
    const { Box, Text } = $.ui.resolve(e)
    // The band's own width: the transcript column's while a Pane is docked.
    const columns = e.props.bodyColumns || (e.viewport?.columns ?? 80)
    const speech = currentSpeech()
    const color = MOOD_COLOR[speech.mood]
    // Goggles down when flying, and at full power (effort raised to max).
    const rows = sceneRows(act, frame, blink, frame, act === 'fly' || isBoosted())
    const working = (WORK_ACTS as readonly Act[]).includes(act)
    const text = working ? `${SPINNER[frame % SPINNER.length]} ${ACT_LABEL[act as (typeof WORK_ACTS)[number]]} · ${speech.text}` : speech.text
    return (
      <Box flexDirection="column">
        <Box key="jev:pet" flexDirection="row" justifyContent="flex-end" alignItems="center" columnGap={1} width={columns} paddingRight={4}>
          {/* The bubble gives way: a long line is cut, the pilot is never squeezed. */}
          <Box key="jev:bubble" borderStyle="round" borderColor={color} paddingX={1} flexShrink={1}>
            <Text key="jev:say" color={color} wrap="truncate-end">
              {text}
            </Text>
          </Box>
          <Box key="jev:sprite" flexDirection="column" flexShrink={0} width={CANVAS_W} minWidth={CANVAS_W}>
            {rows.map((row, y) => (
              <Text key={`jev:row${y}`} wrap="truncate-end">
                {row.map((cell, x) => (
                  <Text key={`jev:${y}:${x}`} color={cell.fg} backgroundColor={cell.bg}>
                    {cell.ch}
                  </Text>
                ))}
              </Text>
            ))}
          </Box>
        </Box>
        {await next(e)}
      </Box>
    )
  })
}

