/**
 * jev-pilot — the decision ledger: what each main-loop turn was decided
 * and what then happened, kept in the plugin's store so the thresholds can be
 * tuned from real sessions instead of defaults.
 *
 * Pure: the hooks read and write `$.store`; this module shapes the entries,
 * keeps the list bounded, and turns it into a report with suggestions. No
 * prompt text is recorded, only labels, numbers and outcomes.
 */

export interface LedgerEntry {
  /** When the turn started, ms since the epoch. */
  at: number
  /** Whether the decision model answered at all (false: timeout, error, no key). */
  answered: boolean
  /** How long the answer took, ms; null when it was not asked. */
  ms: number | null
  tier: string | null
  tierConfidence: number | null
  /** The rubric level acted on (0..4), after the close-call lean. */
  effortLevel: number | null
  effortConfidence: number | null
  /** The effort the engine built the turn with, and the one it started on. */
  startedFrom: string | null
  started: string | null
  /** What trouble raised it to mid-turn, or null. */
  raisedTo: string | null
  toolCalls: number
  /** The longest run of failed tool calls in the turn. */
  failures: number
  strategy: string | null
  strategyConfidence: number | null
  /** Whether strategy advice was attached to the prompt. */
  advised: boolean
  /** How the turn ended: answer, aborted, refusal, error. */
  outcome: string | null
  durationMs: number | null
  outputTokens: number | null
  /** The engine's own id for the turn: what a correction marks it by (absent on entries from before 0.9). */
  id?: string
  /**
   * Whether your next message said this turn got it wrong ("it doesn't work",
   * "not what I asked"), as Jev read it; absent until the next prompt.
   */
  corrected?: boolean
}

/** The ledger with the one entry of turn `id` marked as corrected or not. */
export function markCorrected(stored: unknown, id: string, corrected: boolean): LedgerEntry[] {
  return entriesOf(stored).map((entry) => (entry.id !== undefined && entry.id === id ? { ...entry, corrected } : entry))
}

/** The most entries kept; the oldest go first. */
export const LEDGER_SIZE = 500

export const LEDGER_KEY = 'ledger'

/**
 * The stored list with `entry` appended, bounded to `size`. Whatever is in
 * the store that is not a list of entries (a first run, or a value some
 * older version wrote) starts a fresh list rather than being patched.
 */
export function appendEntry(stored: unknown, entry: LedgerEntry, size = LEDGER_SIZE): LedgerEntry[] {
  const list = Array.isArray(stored) ? stored.filter(isEntry) : []
  list.push(entry)
  return list.slice(-size)
}

function isEntry(value: unknown): value is LedgerEntry {
  return (
    !!value &&
    typeof value === 'object' &&
    typeof (value as LedgerEntry).at === 'number' &&
    typeof (value as LedgerEntry).answered === 'boolean'
  )
}

/** The entries in the store, or none. */
export function entriesOf(stored: unknown): LedgerEntry[] {
  return Array.isArray(stored) ? stored.filter(isEntry) : []
}

/** The settings a suggestion may change, as they are now. */
export interface TunableConfig {
  timeoutMs: number
  minDowngradeConfidence: number
  effortCloseMargin: number
  /** How sure Jev must be to start a turn at high or above. */
  minHighConfidence: number
}

export interface Suggestion {
  option: keyof TunableConfig
  from: number
  to: number
  why: string
}

/** Below this many turns, nothing is suggested: too few to tell noise from a pattern. */
export const MIN_TURNS_TO_SUGGEST = 20

const LEVELS = ['low', 'medium', 'high', 'xhigh', 'max']

function percentile(values: number[], p: number): number | null {
  if (values.length === 0) return null
  const sorted = [...values].sort((a, b) => a - b)
  return sorted[Math.min(sorted.length - 1, Math.floor(p * sorted.length))] as number
}

function share(part: number, whole: number): string {
  return whole === 0 ? '—' : `${Math.round((100 * part) / whole)}%`
}

const round2 = (value: number) => Math.round(value * 100) / 100

/**
 * What the ledger says should change, each with its reason. Conservative by
 * design: one step at a time, only past MIN_TURNS_TO_SUGGEST turns, and only
 * where the evidence points one way.
 */
export function suggestions(entries: readonly LedgerEntry[], config: TunableConfig): Suggestion[] {
  if (entries.length < MIN_TURNS_TO_SUGGEST) return []
  const found: Suggestion[] = []

  // Answers that did not arrive in time: the turns ran unrouted. Only turns
  // where a backend was asked count (`ms` is null when none was, e.g. no key).
  const asked = entries.filter((entry) => entry.ms !== null)
  const missed = asked.filter((entry) => !entry.answered).length
  const p90 = percentile(
    entries.filter((entry) => entry.answered && entry.ms !== null).map((entry) => entry.ms as number),
    0.9,
  )
  if (asked.length > 0 && missed / asked.length > 0.1 && p90 !== null) {
    const to = Math.max(config.timeoutMs + 200, Math.ceil((p90 * 1.25) / 100) * 100)
    found.push({
      option: 'timeoutMs',
      from: config.timeoutMs,
      to,
      why: `${share(missed, asked.length)} of turns got no answer in time; answers that did arrive took up to ${Math.round(p90)} ms (90th percentile)`,
    })
  }

  // Turns started low that had to be raised: the start was too cheap.
  // Trouble at a cheap start: raised mid-turn, or corrected by your next message.
  const startedLow = entries.filter((entry) => entry.started === 'low' || entry.started === 'medium')
  const raisedLow = startedLow.filter((entry) => entry.raisedTo !== null || entry.corrected === true).length
  if (startedLow.length >= 10 && raisedLow / startedLow.length > 0.2) {
    if (config.minDowngradeConfidence < 0.9) {
      found.push({
        option: 'minDowngradeConfidence',
        from: config.minDowngradeConfidence,
        to: round2(Math.min(0.9, config.minDowngradeConfidence + 0.1)),
        why: `${share(raisedLow, startedLow.length)} of turns started at low or medium effort had to be raised mid-turn or were corrected by you`,
      })
    }
    if (config.effortCloseMargin < 0.3) {
      found.push({
        option: 'effortCloseMargin',
        from: config.effortCloseMargin,
        to: round2(Math.min(0.3, config.effortCloseMargin + 0.05)),
        why: 'close calls between two effort levels should lean up more often',
      })
    }
  }

  // Turns started high that ran short and clean: the start may be too costly.
  // Turns started at high that turned out easy: high takes a surer answer.
  const atHigh = entries.filter((entry) => entry.started === 'high')
  const easyAtHigh = atHigh.filter(
    (entry) => entry.raisedTo === null && entry.failures === 0 && entry.toolCalls <= 2 && entry.outcome === 'answer' && entry.corrected !== true,
  ).length
  const raisedUp = found.some((suggestion) => suggestion.option === 'minDowngradeConfidence')
  if (atHigh.length >= 10 && easyAtHigh / atHigh.length > 0.6 && config.minHighConfidence < 0.8 && !raisedUp) {
    found.push({
      option: 'minHighConfidence',
      from: config.minHighConfidence,
      to: round2(Math.min(0.8, config.minHighConfidence + 0.1)),
      why: `${share(easyAtHigh, atHigh.length)} of turns started at high finished in two tool calls or fewer, with no failures`,
    })
  }

  const startedHigh = entries.filter((entry) => entry.started === 'xhigh' || entry.started === 'max')
  const easyHigh = startedHigh.filter(
    (entry) => entry.raisedTo === null && entry.failures === 0 && entry.toolCalls <= 2 && entry.outcome === 'answer' && entry.corrected !== true,
  ).length
  // Evidence pointing both ways is no evidence: then the margin stays.
  const marginUp = found.some((suggestion) => suggestion.option === 'effortCloseMargin')
  if (startedHigh.length >= 10 && easyHigh / startedHigh.length > 0.6 && config.effortCloseMargin > 0 && !marginUp) {
    found.push({
      option: 'effortCloseMargin',
      from: config.effortCloseMargin,
      to: round2(Math.max(0, config.effortCloseMargin - 0.05)),
      why: `${share(easyHigh, startedHigh.length)} of turns started at xhigh or max finished in two tool calls or fewer, with no failures`,
    })
  }
  return found
}

/**
 * The report, as text for the model to show the person: what the ledger
 * holds, per starting effort, and what it suggests changing.
 */
export function summarize(entries: readonly LedgerEntry[], config: TunableConfig): string {
  if (entries.length === 0) {
    return 'The decision ledger is empty: no main-conversation turn has been recorded yet. Use Claude Code as usual and run this again later.'
  }
  const first = new Date(entries[0]!.at).toISOString().slice(0, 10)
  const answered = entries.filter((entry) => entry.answered)
  const latencies = answered.filter((entry) => entry.ms !== null).map((entry) => entry.ms as number)
  const lines = [
    `Decision ledger: ${entries.length} turns since ${first}.`,
    '',
    `Jev answered ${share(answered.length, entries.length)} of turns; latency median ${percentile(latencies, 0.5) ?? '—'} ms, 90th percentile ${percentile(latencies, 0.9) ?? '—'} ms.`,
    '',
    '| Started at | Turns | Raised mid-turn | Corrected by you | Avg tool calls | Avg output tokens |',
    '|---|---|---|---|---|---|',
  ]
  for (const level of LEVELS) {
    const here = entries.filter((entry) => entry.started === level)
    if (here.length === 0) continue
    const raised = here.filter((entry) => entry.raisedTo !== null).length
    const tools = here.reduce((sum, entry) => sum + entry.toolCalls, 0) / here.length
    const withTokens = here.filter((entry) => entry.outputTokens !== null)
    const tokens =
      withTokens.length === 0
        ? '—'
        : String(Math.round(withTokens.reduce((sum, entry) => sum + (entry.outputTokens as number), 0) / withTokens.length))
    // Only turns followed by another prompt could be judged.
    const judged = here.filter((entry) => typeof entry.corrected === 'boolean')
    const corrected = judged.filter((entry) => entry.corrected).length
    lines.push(`| ${level} | ${here.length} | ${share(raised, here.length)} | ${judged.length > 0 ? `${share(corrected, judged.length)} of ${judged.length}` : '—'} | ${tools.toFixed(1)} | ${tokens} |`)
  }
  const unset = entries.filter((entry) => entry.started === null).length
  if (unset > 0) lines.push(`| (not set) | ${unset} | | | | |`)

  const advised = entries.filter((entry) => entry.advised)
  if (advised.length > 0) {
    const counts = new Map<string, number>()
    for (const entry of advised) counts.set(entry.strategy ?? '?', (counts.get(entry.strategy ?? '?') ?? 0) + 1)
    lines.push(
      '',
      `Strategy advice attached on ${advised.length} turns: ${[...counts].map(([name, count]) => `${name} ${count}`).join(', ')}.`,
    )
  }

  const found = suggestions(entries, config)
  lines.push('')
  if (entries.length < MIN_TURNS_TO_SUGGEST) {
    lines.push(`No suggestions yet: they need at least ${MIN_TURNS_TO_SUGGEST} turns.`)
  } else if (found.length === 0) {
    lines.push('No change suggested: nothing in the ledger points one way.')
  } else {
    lines.push('Suggested changes:')
    for (const suggestion of found) {
      lines.push(`- \`${suggestion.option}\`: ${suggestion.from} → ${suggestion.to}, because ${suggestion.why}.`)
    }
  }
  return lines.join('\n')
}

/** The settings keys that hold jev-pilot's options (`jev-pilot`, `jev-pilot@<source>`). */
export function configKeysOf(settingsJson: string): string[] {
  let parsed: unknown
  try {
    parsed = JSON.parse(settingsJson)
  } catch {
    return []
  }
  const configs = parsed && typeof parsed === 'object' ? (parsed as { pluginConfigs?: unknown }).pluginConfigs : null
  if (!configs || typeof configs !== 'object' || Array.isArray(configs)) return []
  return Object.keys(configs).filter((key) => /^jev-pilot(@[^@]+)?$/.test(key))
}

/**
 * The prompt `/jev-pilot:report` hands the model. The settings key depends
 * on how jev-pilot was installed, so a suggested edit names the key found in
 * the settings, or asks when there is none or more than one.
 */
export function reportPrompt(report: string, settingsPath: string, hasSuggestions: boolean, keys: readonly string[] = []): string {
  let where: string
  if (keys.length === 1) {
    where = `the "${keys[0]}" entry under "pluginConfigs" in ${settingsPath} ("options" object)`
  } else if (keys.length > 1) {
    where = `the jev-pilot entry under "pluginConfigs" in ${settingsPath} that this session loads (found: ${keys.map((key) => `"${key}"`).join(', ')}; ask the user which, if it is not clear)`
  } else {
    where = `a new jev-pilot entry under "pluginConfigs" in ${settingsPath}, whose key depends on how jev-pilot was installed: "jev-pilot@jev-pilot" from its marketplace, "jev-pilot@skills-dir" from claude-code-templates --mod, "jev-pilot" with --plugin-dir. Ask the user which before adding it`
  }
  return [
    'Show the user this jev-pilot report exactly as written, as markdown:',
    '',
    report,
    '',
    hasSuggestions
      ? `Then offer to apply the suggested changes to ${where}: one Edit, changing nothing else, and only after the user says yes. The change takes effect in the next session.`
      : 'Do not change any settings.',
  ].join('\n')
}

files.hooks/tuning.ts:
/**
 * jev-pilot — tuning learned from the ledger.
 *
 * Every 20 turns the router reads the decision ledger (ledger.ts) and, when
 * it points one way (low starts that keep getting raised, high starts that
 * finish in two tool calls, answers arriving too late), proposes a change in
 * one line. `/jev tune apply` takes it: the change is kept in the store, on
 * top of your settings, and applies at once. `/jev tune reset` goes back to
 * the settings. Nothing changes without the command.
 *
 * Shared, like crew-state.ts: the router routes with the effective values,
 * the pet module's `/jev` changes them.
 */
import type { LedgerEntry, Suggestion, TunableConfig } from './ledger.ts'
import { MIN_TURNS_TO_SUGGEST, suggestions } from './ledger.ts'

export const TUNING_KEY = 'tuning'

export interface Tuning {
  /** Values changed from the settings. */
  values: Partial<TunableConfig>
  /** When they last changed: only turns after this are evidence for the next change. */
  since: number
}

/** The range each tunable value is kept in, whatever the store holds. */
const RANGES: Record<keyof TunableConfig, [number, number]> = {
  timeoutMs: [300, 5000],
  minDowngradeConfidence: [0, 0.95],
  effortCloseMargin: [0, 0.5],
  minHighConfidence: [0, 0.95],
}

let base: TunableConfig | null = null
let tuning: Tuning = { values: {}, since: 0 }
let loaded = false
let applier: ((config: TunableConfig) => void) | null = null

/** The settings' values, and how to put new ones in force (the router's). */
export function initTuning(from: TunableConfig, apply: (config: TunableConfig) => void): void {
  base = { ...from }
  applier = apply
  tuning = { values: {}, since: 0 }
  loaded = false
}

/** The values in force: the settings with the learned changes on top. */
export function effective(): TunableConfig {
  return { ...(base as TunableConfig), ...tuning.values }
}

export function currentTuning(): Tuning {
  return { values: { ...tuning.values }, since: tuning.since }
}

/** Whether the store has been read in this worker (a reload starts over). */
export function tuningLoaded(): boolean {
  return loaded
}

/** Puts a tuning in force. */
export function setTuning(next: Tuning): void {
  tuning = { values: { ...next.values }, since: next.since }
  loaded = true
  if (base) applier?.(effective())
}

/** A tuning read back from the store: unknown keys dropped, values kept in range. */
export function tuningOf(stored: unknown): Tuning {
  if (!stored || typeof stored !== 'object' || Array.isArray(stored)) return { values: {}, since: 0 }
  const raw = stored as { values?: unknown; since?: unknown }
  const values: Partial<TunableConfig> = {}
  if (raw.values && typeof raw.values === 'object' && !Array.isArray(raw.values)) {
    for (const [key, range] of Object.entries(RANGES) as [keyof TunableConfig, [number, number]][]) {
      const value = (raw.values as Record<string, unknown>)[key]
      if (typeof value === 'number' && Number.isFinite(value)) values[key] = Math.min(range[1], Math.max(range[0], value))
    }
  }
  return { values, since: typeof raw.since === 'number' && Number.isFinite(raw.since) ? raw.since : 0 }
}

/** The turns that count as evidence now: those since the last change. */
export function evidence(entries: readonly LedgerEntry[], since = tuning.since): LedgerEntry[] {
  return entries.filter((entry) => entry.at > since)
}

/** What the ledger suggests now, from the turns since the last change. */
export function proposals(entries: readonly LedgerEntry[]): Suggestion[] {
  return base ? suggestions(evidence(entries), effective()) : []
}

/**
 * Whether to propose after this turn: every 20 turns of new evidence, when
 * the evidence suggests something. Once per 20, so it never nags.
 */
export function dueToPropose(entries: readonly LedgerEntry[]): Suggestion[] {
  const fresh = evidence(entries)
  if (fresh.length < MIN_TURNS_TO_SUGGEST || fresh.length % 20 !== 0) return []
  return proposals(entries)
}

/** The tuning with the suggestions applied, from `now` on. */
export function applied(current: Tuning, found: readonly Suggestion[], now: number): Tuning {
  const values = { ...current.values }
  for (const suggestion of found) values[suggestion.option] = suggestion.to
  return tuningOf({ values, since: now })
}

/** `/jev tune`: what is tuned, and what the ledger suggests. */
export function describeTuning(entries: readonly LedgerEntry[]): string {
  const now = effective()
  const set = base as TunableConfig
  const lines = ['jev-pilot tuning (learned from your ledger; your settings are unchanged):']
  for (const key of Object.keys(RANGES) as (keyof TunableConfig)[]) {
    const tuned = tuning.values[key]
    lines.push(`  ${key.padEnd(24)} ${now[key]}${tuned !== undefined && tuned !== set[key] ? `   (settings: ${set[key]})` : ''}`)
  }
  const fresh = evidence(entries).length
  const found = proposals(entries)
  lines.push('')
  if (found.length > 0) {
    lines.push(`From your last ${fresh} turns, it suggests:`)
    for (const s of found) lines.push(`  ${s.option}: ${s.from} → ${s.to}, because ${s.why}`)
    lines.push('  /jev tune apply takes these · /jev tune reset goes back to your settings')
  } else if (fresh < MIN_TURNS_TO_SUGGEST) {
    lines.push(`No suggestion yet: ${fresh} of the ${MIN_TURNS_TO_SUGGEST} turns it needs since the last change.`)
  } else {
    lines.push(`Nothing to change: your last ${fresh} turns point no one way.`)
  }
  return lines.join('\n')
}

