/**
 * jev-model-router — pure decision logic.
 *
 * No `$` and no I/O here: this module only builds the request the decision
 * API takes, reads its answer, and turns that answer into a model id. The
 * hooks module does every call on `$` at its own call site.
 *
 * Two backends speak to the same model with different wire shapes:
 *
 *   typesafe  POST https://api.typesafe.ai/v1/systemone
 *             `{ model, state, questions }`; a yes/no question is a `noul`
 *             and every answer carries its own `confidence`.
 *   gateway   POST https://ai-gateway.vercel.sh/v4/ai/evaluation-model
 *             `{ state, questions }` with the model in a header; a yes/no
 *             question is a `boolean`, and there is no `confidence` field —
 *             it has to be derived from an optional distribution.
 *
 *   openrouter  POST https://openrouter.ai/api/v1/systemone
 *             OpenRouter's System One route, "compatible with the TypeSafe
 *             SDKs": the same model (`~typesafe/jev-latest`) in TypeSafe's own
 *             wire shape, `{ model, state, questions }`, `noul`, a
 *             `confidence` per answer.
 *
 * The Gateway shape is not documented publicly; it was read from
 * @ai-sdk/gateway and @ai-sdk/provider.
 */

export type Provider = 'typesafe' | 'gateway' | 'openrouter'

export type Tier = 'fast' | 'balanced' | 'deep'

export interface Tiers {
  fast: string
  balanced: string
  deep: string
}

export interface Decision {
  tier: Tier
  /**
   * A custom model slot the decision model chose for a subagent (`alpha`,
   * ...), when it was offered one. The tier then reads as `fast`, the
   * cheapest, so every other rule works as for Claude's own models.
   */
  slot?: string
  /** Confidence in the tier, or null when the backend reported none. */
  confidence: number | null
  /** P(true) that carrying the task out would itself be costly or final. */
  risky: number | null
  /** 0..3 along the effort rubric, or null when absent. */
  effort: number | null
  /** Confidence in the effort, or null when the backend reported none. */
  effortConfidence: number | null
  /** The effort's distribution over rubric levels ("0".."4"), when the backend sent one. */
  effortProbabilities?: Record<string, number> | null
  /** How the work should be carried out, or null when not asked or not answered. */
  strategy?: Strategy | null
  /** Confidence in the strategy, or null when the backend reported none. */
  strategyConfidence?: number | null
  /** The quality reads (see QUALITY_QUESTIONS): P(true) each, when asked and answered. */
  corrects?: number | null
  underspecified?: number | null
  sensitive?: number | null
  bugfix?: number | null
}

/**
 * How a task is carried out: by the main conversation itself, by one
 * subagent, by several at once, or by a small graph of subagents in waves.
 */
export type Strategy = 'direct' | 'delegate' | 'parallel' | 'graph' | 'junior'

export const STRATEGY_ORDER: readonly Strategy[] = ['direct', 'delegate', 'parallel', 'graph']
/** `junior` is offered only in junior-lead mode, with a junior to hand work to. */
const ALL_STRATEGIES: readonly Strategy[] = [...STRATEGY_ORDER, 'junior']

/**
 * How each strategy is described to the decision model. Written so that
 * `direct` is the ordinary answer: every other one spends subagents, and
 * a subagent re-reads what the main conversation already knows.
 */
const STRATEGY_CRITERIA: Record<Strategy, string> = {
  direct:
    'The main conversation does it itself: a question, a lookup, a command, or a change to one or a few files. One job with one clear finish line. The right answer for most requests, including most follow-ups.',
  delegate:
    'One subagent on a cheaper model does a broad but mechanical part first (searching or reading across many files, a codebase sweep, bulk renames) and the main conversation acts on its short report.',
  parallel:
    'Fan out, then join: several independent pieces with no shared files or state (separate modules, services or investigations), each done by its own subagent at the same time, then combined in one place.',
  graph:
    'Work one conversation would lose track of: parts that depend on each other in waves, or distinct specialties that hand off (build, then an independent review, then fixes), with results fanning in to be checked. Only for large builds; most work, even big work, is direct or parallel.',
  junior:
    'An easy coding change that is already well specified (which files, what behavior, a test or command that proves it): a cheaper junior model writes it, and the main conversation reviews the diff as the tech lead. Not for design, unclear bugs or risky changes.',
}

/**
 * The two sides of the risk question, as a noul's `criteria`: the act of
 * carrying the task out, not the subject it is about.
 */
const RISK_CRITERIA = {
  true: 'Doing the task runs something against a real system with lasting effect: deploying or releasing, changing production data or configuration, moving money, deleting or overwriting data with no backup, or rewriting shared history (force-push).',
  false: 'Reading, explaining, planning, or writing and testing code locally, even code that deals with production, payments or data, without running it against the real system.',
}

/**
 * What Jev reads about a request to make the work better, not cheaper, asked
 * in the same request as the effort (no extra wait). Each wording measured
 * on sample prompts: `corrects` 0.95+ on "it doesn't work / not what I
 * asked" and 0.34 at most otherwise; `bugfix` 0.91+ on bug reports; `sensitive`
 * 0.84+ on money, migrations and permissions; `underspecified` 0.86+ on vague
 * asks ("add caching", "make it better") and 0.78 at most on concrete ones
 * (a first wording scored "add a dark mode toggle" 0.86, so what a capable
 * engineer decides alone is ruled out in the question).
 */
export const QUALITY_QUESTIONS: Record<'corrects' | 'underspecified' | 'sensitive' | 'bugfix', { instructions: string; criteria: { true: string; false: string } }> = {
  corrects: {
    instructions: "The user's latest message tells the assistant that its previous answer or work was wrong, broken, incomplete, or not what was asked, and asks for it to be fixed or redone.",
    criteria: {
      true: "The message reports a problem with what the assistant just did or said: it doesn't work, it's wrong, it missed something, it's not what was asked, try again.",
      false: 'The message approves, continues, asks something new, or gives a new task; or there was no previous answer.',
    },
  },
  underspecified: {
    instructions:
      "Before starting, the assistant would have to guess what the user wants, because the request can reasonably mean quite different things that lead to different code, and a wrong guess would waste the work. Details a capable engineer decides without asking (names, layout, sensible defaults, where to put a file) don't count.",
    criteria: {
      true: 'Vague or open-ended: what to build or how it should behave is not said, e.g. "make it better", "add caching", "add rate limiting" with no limits, keys or storage given.',
      false:
        'A concrete task an engineer could just do, filling small gaps with sensible defaults, e.g. "add a dark mode toggle to settings", "add a test for X", "rename A to B", "change the color to blue"; or a question, or an approval.',
    },
  },
  sensitive: {
    instructions:
      'The requested change is to code where a bug is costly: authentication or permissions, payments or money, stored data or migrations, security or secrets, concurrency, or an interface other code depends on.',
    criteria: {
      true: 'Getting this change subtly wrong could lose data or money, let in the wrong user, leak something, or break other code.',
      false: 'A mistake here would be visible and cheap to fix: styling, wording, a script, a test, docs, a small internal helper; or it is not a code change.',
    },
  },
  bugfix: {
    instructions: 'The latest request asks to fix a bug: something behaves wrongly (an error, a crash, a failing test, a wrong result) and should be made to behave right.',
    criteria: {
      true: 'Something works wrong and the user wants it to work right.',
      false: 'A new feature, a change of behavior on purpose, a refactor, a question, docs, or an approval.',
    },
  },
}

/** How sure Jev must be before each read changes anything. */
export const QUALITY_BARS = { corrects: 0.7, underspecified: 0.85, sensitive: 0.8, bugfix: 0.8 }

/**
 * The advice a request's quality reads call for, as one block for the model
 * (advice to weigh, like the strategy), or null. `reviewer` is the external
 * reviewer to name for sensitive changes, when one is working.
 */
export function qualityAdvice(decision: Decision | null): string | null {
  if (!decision) return null
  const sure = (value: number | null | undefined, bar: number) => typeof value === 'number' && value >= bar
  // Each check is asked for in one place only (a review is the crew's note's
  // to ask for), and none is a procedure to perform and narrate: rituals
  // make Opus 5.5 write more and repeat tool calls (prompt-audit, 2026-09-26).
  const lines: string[] = []
  if (sure(decision.underspecified, QUALITY_BARS.underspecified)) {
    lines.push("- It leaves open what to build or how it should behave. Before writing code, ask the user one short question, or state in one line the assumption you're making and go on.")
  }
  if (sure(decision.bugfix, QUALITY_BARS.bugfix)) {
    lines.push('- It is likely a bug fix. If a test or command can reproduce it cheaply, use it as your check before and after the fix.')
  }
  if (sure(decision.sensitive, QUALITY_BARS.sensitive)) {
    lines.push('- It touches code where a bug is costly. Make sure a test covers the case you changed.')
  }
  if (lines.length === 0) return null
  return ['<jev_quality>', "Jev's read of this request:", ...lines, '</jev_quality>'].join('\n')
}

/** The reasoning levels a turn can ask for, cheapest first. */
export const EFFORT_ORDER = ['low', 'medium', 'high', 'xhigh', 'max'] as const

export type Effort = (typeof EFFORT_ORDER)[number]

export const TIER_ORDER: readonly Tier[] = ['fast', 'balanced', 'deep']

/**
 * How each tier is described to the decision model. Deliberately about the
 * shape of the work, not about model names: the model never sees an id.
 */
const TIER_CRITERIA: Record<Tier, string> = {
  fast: 'Haiku. Choose for read-only lookups where a mistake is cheap to spot: search or list files, find where something is defined, read files, logs or test output and report what is there, run a command and report the result. Nothing is written or changed.',
  balanced:
    'Sonnet. Choose for read-only work that needs some understanding (summarize or explain code, research across many files, review a diff and report the findings), and for code changes with a clear spec and a way to check the result: the brief says what to change and a test, build or type check shows it works, such as a bug fix whose cause is known, a feature to a written spec, tests for existing code, or a scoped refactor.',
  deep: 'Opus. Choose for work that needs careful judgment or runs long: design, a change whose spec is open or that nothing can check, a bug whose cause is unknown, long multi-step work across many components, security, data migrations, production or money.',
}

/**
 * The effort rubric, one level per rung of EFFORT_ORDER. Each level names the
 * kind of task that needs it, not an amount ("some", "a lot"): an amount
 * leaves the decision model to guess what it means for code, a kind of task
 * is something it can recognise in the request.
 */
const EFFORT_RUBRIC = [
  'Answered from what is already known, or mechanical work with nothing to work out: a lookup, a single command, a rename or find-and-replace (even across many files), a search that lists what it finds, formatting, a one-line change.',
  'An ordinary, well-specified change to one or a few files, or a direct question about code already in view.',
  'A change across several files that needs working out, a bug whose cause is described but has to be traced, writing tests, or reviewing a diff with care.',
  'Design across several components, a bug whose cause is unknown, a refactor with many dependents, or careful reasoning about concurrency, performance or failure modes.',
  'Novel architecture, a security or data-integrity question, a failure that resisted earlier attempts, or work where a subtle mistake is costly and hard to undo.',
] as const

export const DEFAULT_BASE_URL: Record<Provider, string> = {
  typesafe: 'https://api.typesafe.ai',
  gateway: 'https://ai-gateway.vercel.sh/v4/ai',
  openrouter: 'https://openrouter.ai/api',
}

/**
 * The Gateway's own protocol version, sent as `ai-gateway-protocol-version`.
 * Tracks the `AI_GATEWAY_PROTOCOL_VERSION` of `@ai-sdk/gateway` (4.0.87).
 */
const AI_GATEWAY_PROTOCOL_VERSION = '0.0.1'

export const DEFAULT_MODEL: Record<Provider, string> = {
  typesafe: 'jev-latest',
  gateway: 'typesafe-ai/jev',
  openrouter: '~typesafe/jev-latest',
}

/**
 * Which backend a configuration asks for, or null for the built-in
 * classifier. `auto` prefers the backends that report a calibrated
 * confidence — TypeSafe's own API, then OpenRouter — over the Gateway, which
 * does not; a forced backend whose key is missing resolves to
 * null rather than falling through to the other one's key.
 */
export function selectProvider(
  forced: string,
  typesafeKey: string,
  gatewayKey: string,
  openrouterKey = '',
): Provider | null {
  if (forced === 'builtin') return null
  if (forced === 'typesafe') return typesafeKey ? 'typesafe' : null
  if (forced === 'gateway') return gatewayKey ? 'gateway' : null
  if (forced === 'openrouter') return openrouterKey ? 'openrouter' : null
  if (typesafeKey) return 'typesafe'
  if (openrouterKey) return 'openrouter'
  if (gatewayKey) return 'gateway'
  return null
}

/** The full endpoint a backend posts to. */
export function endpoint(provider: Provider, baseUrl: string): string {
  const root = baseUrl.replace(/\/+$/, '')
  // OpenRouter serves TypeSafe's own route under its API root.
  return provider === 'gateway' ? `${root}/evaluation-model` : `${root}/v1/systemone`
}

/**
 * The `questions` map, in the shape the backend's schema names. The strategy
 * is asked only for the main conversation: a subagent is already one part of
 * a split, and its own is not this router's to decide.
 */
/**
 * The effort question for a subagent's brief. Asked as for a conversation,
 * a planner's detailed brief (files, steps, tests, stakes) reads as hard in
 * itself; what the subagent needs is the reasoning to carry it out. Measured
 * on 14 real builder and fixer briefs: 10 read as xhigh with the general
 * question, 1 with this one (the brief that asked for a design).
 */
export const SUBAGENT_EFFORT_INSTRUCTIONS =
  'How much step-by-step reasoning does a subagent need to carry out this brief? A brief that already names the files, the steps and the tests has done the design: carrying it out is execution. Rate higher only when the brief itself asks for design, an unknown cause, or reasoning that is not already written out. Rate the work, not how important the topic sounds: reviewing a small diff is medium, even for security.'

/**
 * The effort question for the conversation. Measured on 76 labelled real
 * requests: rating the topic instead of the work put 8 of 26 medium tasks
 * (advice questions, small security reviews) at xhigh; this wording, with
 * the follow-up rule in `route`, took the misses of 2+ levels from 19 to 9.
 */
export const EFFORT_INSTRUCTIONS =
  'How much step-by-step reasoning does the work this request asks for need? Rate the work, not how important the topic sounds: a question or advice answered in words, even about architecture or security, is low or medium, and reviewing a small diff is medium. A short reply that approves, continues or picks an option ("go ahead", "fix all and continue", "1") takes the size of the work it approves, from the recent conversation.'

/**
 * A short reply that is not a question ("fix all and continue", "ok go
 * ahead", "1"): it continues or approves work, so its own words say nothing
 * about how big that work is. Such a reply never lowers the effort.
 */
export function isFollowUp(prompt: string): boolean {
  const text = prompt.trim()
  if (!text || /[?？]$/.test(text)) return false
  if (/^(what|why|how|is|are|do|does|did|can|could|should|where|when|which|who)\b/i.test(text)) return false
  if (CJK_QUESTION.test(text)) return false
  return wordCount(text) <= 8
}

/** Han and kana: written without spaces, so splitting on spaces sees one word. */
const UNSPACED = /[぀-ヿ㐀-䶿一-鿿豈-﫿]/gu

/** A Chinese question: a question word anywhere, or 吗/呢 closing it. */
const CJK_QUESTION = /为什么|为啥|怎么|怎样|如何|什么|是不是|能不能|可不可以|有没有|是否|[吗呢][\s。.!！~～]*$/

/**
 * Words the way the eight-word bar counts them: runs of letters or digits
 * between spaces, plus about one word per 1.5 Han or kana characters (the
 * length of an English translation), so a long Chinese request is not one
 * "word". Punctuation alone is not a word.
 */
export function wordCount(text: string): number {
  const unspaced = text.match(UNSPACED)?.length ?? 0
  const spaced = text.replace(UNSPACED, ' ').split(/\s+/).filter((token) => /[\p{L}\p{N}]/u.test(token)).length
  return spaced + Math.ceil(unspaced / 1.5)
}

/**
 * The effort question's options, one per rung of EFFORT_ORDER, each saying
 * when to choose it (the rubric's levels). Asked as a choice, not a score:
 * measured on 76 labelled real requests, named options halved the answers
 * off by two or more levels (9 to 5) and got more medium tasks right (7 to
 * 10 of 26), with its misses balanced instead of mostly too high.
 */
export const EFFORT_CHOICES: Record<Effort, string> = Object.fromEntries(
  EFFORT_ORDER.map((level, index) => [level, EFFORT_RUBRIC[index] as string]),
) as Record<Effort, string>

export function questions(provider: Provider, withStrategy = false, subagent = false, slots: readonly SlotChoice[] = [], junior = false, withQuality = false): Record<string, unknown> {
  // Custom models, when offered, take the cheap end: they replace Haiku as
  // the choice for work with nothing to judge (offered beside it, Jev split
  // its answer between the two), each saying when to choose it.
  const tierCriteria: Record<string, string> = slots.length > 0 ? { balanced: TIER_CRITERIA.balanced, deep: TIER_CRITERIA.deep } : { ...TIER_CRITERIA }
  for (const slot of slots) tierCriteria[slot.name] = `${slot.model} (a custom model, not Claude). ${slot.when}`
  const asked: Record<string, unknown> = {
    tier: {
      type: 'choice',
      instructions: 'Which is the cheapest tier that can complete this coding task well?',
      criteria: tierCriteria,
    },
    effort: {
      type: 'choice',
      instructions: subagent ? SUBAGENT_EFFORT_INSTRUCTIONS : EFFORT_INSTRUCTIONS,
      criteria: EFFORT_CHOICES,
    },
    risky: {
      // The same question under two names: `noul` on TypeSafe's own API and
      // OpenRouter's, `boolean` in the AI SDK's evaluation schema.
      type: provider === 'gateway' ? 'boolean' : 'noul',
      // Asked about the act, not the subject. The first wording ("the task
      // touches production, money, credentials") scored 0.96 on "add a
      // refund endpoint that calls Stripe" — ordinary code that happens to be
      // about money — and would have escalated it past a 0.98-confidence
      // answer of the balanced tier.
      instructions:
        'Carrying out this task would itself change production, move real money, or alter data that cannot be restored. Writing or testing code that deals with such things, without running it against the real system, does not count.',
      // What true and false look like, where the schema takes them (a noul
      // does; the Gateway's boolean is sent with the instructions alone).
      ...(provider === 'gateway' ? {} : { criteria: RISK_CRITERIA }),
    },
  }
  if (withQuality) {
    for (const [name, question] of Object.entries(QUALITY_QUESTIONS)) {
      asked[name] = provider === 'gateway' ? { type: 'boolean', instructions: question.instructions } : { type: 'noul', instructions: question.instructions, criteria: question.criteria }
    }
  }
  if (withStrategy) {
    asked.strategy = {
      type: 'choice',
      instructions:
        'How should a coding assistant carry out the latest request, given the recent conversation? Prefer the simplest way that does it well.',
      // `junior` only when there is a junior to hand the work to.
      criteria: junior ? STRATEGY_CRITERIA : Object.fromEntries(STRATEGY_ORDER.map((name) => [name, STRATEGY_CRITERIA[name]])),
    }
  }
  return asked
}

/** The request body. The Gateway carries the model in a header instead. */
export function requestBody(
  provider: Provider,
  state: Record<string, unknown>,
  model: string,
  withStrategy = false,
  subagent = false,
  slots: readonly SlotChoice[] = [],
  junior = false,
  /** Another module's questions, asked in the same request (the skill pick). */
  extra: Record<string, unknown> = {},
  withQuality = false,
): string {
  const asked = { ...questions(provider, withStrategy, subagent, slots, junior, withQuality), ...extra }
  const body = provider !== 'gateway' ? { model, state, questions: asked } : { state, questions: asked }
  return JSON.stringify(body)
}

/** How jev-pilot names itself to OpenRouter. */
export const OPENROUTER_APP = {
  'http-referer': 'https://github.com/Akramovic1/jev-pilot',
  'x-openrouter-title': 'jev-pilot',
  'x-title': 'jev-pilot',
}

/** The request headers. */
export function requestHeaders(
  provider: Provider,
  apiKey: string,
  model: string,
): Record<string, string> {
  const common = { 'content-type': 'application/json', authorization: `Bearer ${apiKey}` }
  if (provider === 'typesafe') return common
  // Optional on OpenRouter; names the app in its dashboard and logs.
  // OpenRouter attributes requests to an app by these (its app rankings,
  // the model page's "top apps"); both title spellings are accepted.
  if (provider === 'openrouter') return { ...common, ...OPENROUTER_APP }
  return {
    ...common,
    'ai-gateway-auth-method': 'api-key',
    'ai-model-id': model,
    // The Gateway rejects any request that does not name the protocol it
    // speaks: 400 "Unsupported gateway protocol version". Every other header
    // here is accepted without it, so the omission fails the whole backend.
    'ai-gateway-protocol-version': AI_GATEWAY_PROTOCOL_VERSION,
    'ai-evaluation-model-specification-version': '4',
  }
}

/** A custom model offered as a choice: its slot name, the model, and when to choose it. */
export interface SlotChoice {
  name: string
  model: string
  when: string
}

function isTier(value: unknown): value is Tier {
  return value === 'fast' || value === 'balanced' || value === 'deep'
}

/**
 * Reads a response from either backend.
 *
 * TypeSafe's own API reports a `confidence` per answer and a `noul` number
 * for a yes/no question. The Gateway reports neither: confidence has to come
 * from the highest probability of a distribution that is itself optional, and
 * a yes/no answer arrives as `probability`. Both are handled, and a missing
 * confidence reads as null rather than as a number the policy would trust.
 */
export function readDecision(responseText: string, slots: readonly string[] = []): Decision | null {
  let parsed: unknown
  try {
    parsed = JSON.parse(responseText)
  } catch {
    return null
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null
  const answers = (parsed as { answers?: Record<string, Record<string, unknown>> }).answers
  if (!answers || typeof answers !== 'object' || Array.isArray(answers)) return null

  const tierAnswer = answers.tier
  // A custom slot reads as the cheapest tier, with the slot named beside it.
  const slot = tierAnswer && typeof tierAnswer.choice === 'string' && slots.includes(tierAnswer.choice) ? tierAnswer.choice : undefined
  if (!tierAnswer || (!slot && !isTier(tierAnswer.choice))) return null

  const effortAnswer = answers.effort
  const risky = nounOf(answers.risky)

  // The strategy is optional: a request that did not ask it, or an answer
  // naming something else, leaves it null and the rest of the decision stands.
  const strategyAnswer = answers.strategy
  const strategy = isStrategy(strategyAnswer?.choice) ? strategyAnswer.choice : null

  // Effort comes as a choice (a level name, probabilities by name) or, from
  // an older question, a score (0..4, probabilities keyed "0".."4"). Both
  // read the same: probabilities by rung, and their mean as the score.
  const rawProbabilities = effortAnswer?.probabilities
  const byName = rawProbabilities && typeof rawProbabilities === 'object' && !Array.isArray(rawProbabilities) ? (rawProbabilities as Record<string, unknown>) : null
  let effortProbabilities: Record<string, number> | null = null
  let effort: number | null = typeof effortAnswer?.score === 'number' ? effortAnswer.score : null
  if (byName && EFFORT_ORDER.some((level) => typeof byName[level] === 'number')) {
    effortProbabilities = Object.fromEntries(EFFORT_ORDER.map((level, index) => [String(index), typeof byName[level] === 'number' ? (byName[level] as number) : 0]))
    effort = EFFORT_ORDER.reduce((sum, _level, index) => sum + index * (effortProbabilities as Record<string, number>)[String(index)]!, 0)
  } else if (typeof effortAnswer?.choice === 'string' && (EFFORT_ORDER as readonly string[]).includes(effortAnswer.choice)) {
    effort = EFFORT_ORDER.indexOf(effortAnswer.choice as Effort)
  } else if (byName) {
    effortProbabilities = byName as Record<string, number>
  }
  return {
    tier: slot ? 'fast' : (tierAnswer.choice as Tier),
    ...(slot ? { slot } : {}),
    confidence: confidenceOf(tierAnswer),
    effort,
    effortConfidence: effortAnswer ? confidenceOf(effortAnswer) : null,
    effortProbabilities,
    risky,
    strategy,
    strategyConfidence: strategy && strategyAnswer ? confidenceOf(strategyAnswer) : null,
    // Only the quality reads that were asked and answered.
    ...Object.fromEntries(
      (['corrects', 'underspecified', 'sensitive', 'bugfix'] as const).flatMap((name) => {
        const value = nounOf(answers[name])
        return value === null ? [] : [[name, value]]
      }),
    ),
  }
}

/** A noul's P(true) (or a Gateway boolean's probability), or null when not asked or not answered. */
function nounOf(answer: Record<string, unknown> | undefined): number | null {
  if (typeof answer?.noul === 'number') return answer.noul
  if (typeof answer?.probability === 'number') return answer.probability
  return null
}

function isStrategy(value: unknown): value is Strategy {
  return typeof value === 'string' && (ALL_STRATEGIES as readonly string[]).includes(value)
}

/**
 * How sure an answer is. TypeSafe reports it; the Gateway does not, so there
 * it is the highest probability of a distribution that is itself optional.
 */
function confidenceOf(answer: Record<string, unknown>): number | null {
  if (typeof answer.confidence === 'number') return answer.confidence
  const probabilities = answer.probabilities as Record<string, number> | undefined
  const values = probabilities ? Object.values(probabilities) : []
  return values.length > 0 ? Math.max(...values) : null
}

/** The rubric level for "hard": the lean on close calls goes no higher. */
const HARD = 2

/**
 * How sure the decision model must be that a task is very hard (xhigh or
 * max, together) to act on it: above `high`, each rung costs a lot, so a
 * near split between hard and very hard stays at hard.
 */
export const VERY_HARD_CONFIDENCE = 0.6

/**
 * The rubric level to act on; null without an effort answer.
 *
 * Under-thinking a hard task costs more than over-thinking an easy one, so up
 * to `high` a close call leans up: with a distribution, the runner-up is
 * taken when it is higher (at most `high`) and within `margin` of the top;
 * with a bare score, a fraction at or above `0.5 - margin` rounds up (at most
 * to `high`). A margin of 0 is plain rounding and the plain top.
 *
 * Above `high` the bar is how sure the model is: `xhigh` or `max` only when
 * those two together hold at least `veryHard` of the answer, and `xhigh` when
 * they do even though `high` alone came top.
 */
export function effortScoreOf(
  decision: Pick<Decision, 'effort' | 'effortProbabilities'>,
  margin: number,
  veryHard = VERY_HARD_CONFIDENCE,
): number | null {
  const top = EFFORT_ORDER.length - 1
  const ranked = Object.entries(decision.effortProbabilities ?? {})
    .map(([level, probability]) => ({ level: Number(level), probability }))
    .filter(
      (entry) =>
        Number.isInteger(entry.level) &&
        entry.level >= 0 &&
        entry.level <= top &&
        typeof entry.probability === 'number' &&
        Number.isFinite(entry.probability),
    )
    .sort((a, b) => b.probability - a.probability || b.level - a.level)
  const [best, second] = ranked
  if (best) {
    let level = best.level
    if (second && second.level > level && second.level <= HARD && best.probability - second.probability <= margin) level = second.level
    const veryHardShare = ranked.filter((entry) => entry.level > HARD).reduce((sum, entry) => sum + entry.probability, 0)
    if (level > HARD && veryHardShare < veryHard) return HARD
    if (level <= HARD && veryHardShare >= veryHard) return HARD + 1
    return level
  }
  if (decision.effort === null || !Number.isFinite(decision.effort)) return null
  const score = Math.min(top, Math.max(0, decision.effort))
  const whole = Math.floor(score)
  const lean = whole + 1 <= HARD ? margin : 0
  return Math.min(top, score - whole >= 0.5 - lean ? whole + 1 : whole)
}

/** The rubric score (0..4) as a reasoning level. */
export function effortLevel(score: number): Effort {
  const index = Math.min(EFFORT_ORDER.length - 1, Math.max(0, Math.round(score)))
  return EFFORT_ORDER[index] as Effort
}

/**
 * Where a reasoning level sits on the ladder, or null when its place cannot
 * be known (a numeric effort, or a name the ladder does not have).
 */
export function effortRank(effort: string | number | undefined): number | null {
  if (typeof effort !== 'string') return null
  const index = EFFORT_ORDER.indexOf(effort as Effort)
  return index === -1 ? null : index
}

/**
 * Where a model id sits on the tier ladder, by matching it against the
 * configured tier names first and then the family words. Null when it matches
 * none, in which case the change is treated as an upgrade rather than guessed
 * at: an unrecognised id gets the gentler threshold, never the strict one.
 */
export function rankOf(model: string, tiers: Tiers): number | null {
  const lowered = model.toLowerCase()
  for (let index = 0; index < TIER_ORDER.length; index++) {
    const tier = TIER_ORDER[index] as Tier
    const configured = tiers[tier].toLowerCase()
    if (configured && lowered.includes(configured)) return index
  }
  if (lowered.includes('haiku')) return 0
  if (lowered.includes('sonnet')) return 1
  if (lowered.includes('opus')) return 2
  return null
}

/** The model families a tier alias names. */
export type Family = 'haiku' | 'sonnet' | 'opus'

const FAMILIES: readonly Family[] = ['haiku', 'sonnet', 'opus']

/** Which family a model id or alias belongs to, or null for none of them. */
export function familyOf(model: string): Family | null {
  const lowered = model.toLowerCase()
  return FAMILIES.find((family) => lowered.includes(family)) ?? null
}

/**
 * The version in an id of the `claude-<family>-<major>[-<minor>]` shape, as
 * numbers to compare (`claude-opus-5-5[1m]` → [5, 5]; a date suffix is not
 * part of it), or null for an id of another shape.
 */
function versionOf(id: string, family: Family): number[] | null {
  const match = new RegExp(`claude-${family}-(\\d+)(?:-(\\d{1,2}))?(?!\\d)`).exec(id.toLowerCase())
  if (!match) return null
  return [Number(match[1]), ...(match[2] === undefined ? [] : [Number(match[2])])]
}

/** Whether version `a` is newer than `b`; a missing version is the oldest. */
function newer(a: number[] | null, b: number[] | null): boolean {
  if (!a) return false
  if (!b) return true
  for (let index = 0; index < Math.max(a.length, b.length); index++) {
    const left = a[index] ?? 0
    const right = b[index] ?? 0
    if (left !== right) return left > right
  }
  return false
}

/**
 * The full model id of each family, as the engine itself resolved them this
 * session: no version is written in this file, so a new release is picked up
 * as soon as the engine uses it.
 *
 * `agent.spawn` takes an alias (`haiku`) the way the Agent tool does, and the
 * engine resolves it to its current model. `turn.step`'s `model`, though, is
 * sent to the API as written, and an alias there is refused. So every step's
 * resolved id (the main loop's and each subagent's) is learned here, and a
 * main-loop switch to a family uses the newest id seen for it. A family never
 * seen this session has no id, and the switch is not made.
 */
export function modelIds(): {
  learn(id: string): void
  idFor(family: Family): string | null
} {
  const seen = new Map<Family, string>()
  return {
    learn(id) {
      const family = familyOf(id)
      // An alias is not an id: nothing to learn from it.
      if (!family || id.trim().toLowerCase() === family) return
      const held = seen.get(family)
      if (!held || newer(versionOf(id, family), versionOf(held, family))) seen.set(family, id)
    },
    idFor(family) {
      return seen.get(family) ?? null
    },
  }
}

/**
 * What to write into `turn.step`'s `model`: a full id or custom name as given,
 * or, for a family alias, the id learned for it; null when that family has
 * not been seen yet, which leaves the model as the engine built it.
 */
export function requestModelId(model: string, ids: { idFor(family: Family): string | null }): string | null {
  const alias = model.trim().toLowerCase()
  return (FAMILIES as readonly string[]).includes(alias) ? ids.idFor(alias as Family) : model
}

export interface PolicyConfig {
  tiers: Tiers
  /**
   * How sure the decision must be to spend more (a bigger model, more
   * reasoning). Being wrong here costs money, so the bar is low.
   */
  minUpgradeConfidence: number
  /**
   * The bar for raising the effort to `high` or above: those rungs cost the
   * most, so the model must be surer than for low to medium. Measured on 76
   * labelled real requests from a medium session, 0.5 halved the turns sent
   * to high or above (25 to 13) and got 6 more medium tasks right. 0.5 when
   * absent.
   */
  minHighConfidence?: number
  /**
   * How sure it must be to spend less. Being wrong here means a task handled
   * by too small a model or too little thought, so the bar is high.
   */
  minDowngradeConfidence: number
  /**
   * How close two effort levels must be for the higher to win (see
   * `effortScoreOf`); 0 when absent.
   */
  closeMargin?: number
  /**
   * The highest reasoning level a turn may start at; `max` when absent (the
   * hooks default it to `xhigh`). It caps what the router sets, and never
   * pulls a turn already above it down. A struggling turn is raised against
   * its own ceiling instead (see `escalate`).
   */
  maxEffort?: Effort
}

/** The configured ceiling as a rung, `max` for anything not on the ladder. */
function ceilingOf(config: { maxEffort?: Effort }): number {
  const rank = effortRank(config.maxEffort)
  return rank === null ? EFFORT_ORDER.length - 1 : rank
}

export interface Routing {
  /** The model to run on, or null to leave the request as it is. */
  model: string | null
  /** The reasoning level to ask for, or null to leave it as it is. */
  effort: Effort | null
  /** Why, for the log line. */
  reason: string
}

const NOTHING: Routing = { model: null, effort: null, reason: 'no decision' }

/**
 * Whether a change of rank passes its threshold. Both directions are allowed;
 * they just do not have to clear the same bar, because the two mistakes do not
 * cost the same. A move whose direction cannot be told (an unrecognised
 * current value) is treated as an upgrade.
 */
function allowed(
  wanted: number,
  current: number | null,
  confidence: number | null,
  config: PolicyConfig,
): boolean {
  if (current !== null && wanted === current) return false
  const isDowngrade = current !== null && wanted < current
  const bar = isDowngrade ? config.minDowngradeConfidence : config.minUpgradeConfidence
  // A backend that reports no confidence (the Gateway without a distribution,
  // or the built-in classifier) clears the upgrade bar but never the
  // downgrade one: spending less on an unmeasured hunch is the bad trade.
  if (confidence === null) return !isDowngrade
  return confidence >= bar
}

/**
 * Turns a decision into a model and a reasoning level, either of which may be
 * null to leave the request as it is. Both can move in either direction.
 */
export function route(
  decision: Decision | null,
  current: { model: string; effort?: string | number },
  config: PolicyConfig,
  hints: { noLowering?: boolean } = {},
): Routing {
  if (!decision) return NOTHING

  let tier = decision.tier
  let effortScore = effortScoreOf(decision, config.closeMargin ?? 0)
  let forced = false

  // Carrying out something final is never worth the saving: take the deep
  // tier and real reasoning, whatever the cheaper answer said, and skip the
  // thresholds — this is the one case that is not a confidence question.
  if (decision.risky !== null && decision.risky > 0.7) {
    tier = 'deep'
    effortScore = Math.max(effortScore ?? 0, 2)
    forced = true
  }

  const wantedTier = TIER_ORDER.indexOf(tier)
  const currentTier = rankOf(current.model, config.tiers)
  const wantedModel = config.tiers[tier]

  const model =
    wantedModel &&
    wantedModel !== current.model &&
    // Risk skips the confidence bars, not the same-tier check: a deep model
    // stays as it is (a swap to the tier's alias would only bust the cache).
    (currentTier === null || wantedTier !== currentTier) &&
    (forced || allowed(wantedTier, currentTier, decision.confidence, config))
      ? wantedModel
      : null

  let effort: Effort | null = null
  if (effortScore !== null) {
    const currentRank = effortRank(current.effort)
    let wantedRank = Math.min(EFFORT_ORDER.indexOf(effortLevel(effortScore)), ceilingOf(config))

    // Risk raises the floor; it must never lower one. Forcing only skips the
    // thresholds, so without this clamp a task already at `xhigh` or `max`
    // and rated mechanically simple would be pulled down to `high` with no
    // confidence check at all — the opposite of what the rule is for.
    if (forced && currentRank !== null) wantedRank = Math.max(wantedRank, currentRank)
    // The risk floor is a safety rule, the ceiling a cost one: the floor wins,
    // even under a `maxEffort` set below it.
    if (forced) wantedRank = Math.max(wantedRank, EFFORT_ORDER.indexOf('high'))

    // A numeric effort is the caller's own scale, not this ladder; leave it.
    const comparable = typeof current.effort !== 'number'
    const wanted = EFFORT_ORDER[Math.min(EFFORT_ORDER.length - 1, wantedRank)] as Effort
    // Above the ceiling already (set by hand): the ceiling limits what this
    // router asks for, it is not a reason to cut what the person chose.
    const aboveCeiling = currentRank !== null && currentRank > ceilingOf(config)
    // A short follow-up approves or continues work its words don't describe:
    // it may raise the effort, never lower it.
    const lowering = currentRank !== null && wantedRank < currentRank
    // Raising to high or above takes a surer answer than a raise to medium.
    const toHigh = !lowering && wantedRank >= EFFORT_ORDER.indexOf('high')
    const sureOfHigh = decision.effortConfidence === null || decision.effortConfidence >= (config.minHighConfidence ?? 0.5)
    if (
      comparable &&
      !aboveCeiling &&
      !(hints.noLowering && lowering) &&
      wantedRank !== currentRank &&
      (forced || (allowed(wantedRank, currentRank, decision.effortConfidence, config) && (!toHigh || sureOfHigh)))
    ) {
      effort = wanted
    }
  }

  const said = decision.confidence === null ? 'confidence n/d' : `confidence ${decision.confidence.toFixed(2)}`

  if (!model && !effort) {
    // Naming what it wanted and what it kept is the whole point of this line.
    // Without it, a mod that classified and decided to leave the request alone
    // is indistinguishable from one that never loaded.
    const wantedEffort = effortScore === null ? null : effortLevel(effortScore)
    const kept = `${current.model}${current.effort === undefined ? '' : `/${current.effort}`}`
    const wanted = `${wantedModel}${wantedEffort ? `/${wantedEffort}` : ''}`
    return { model: null, effort: null, reason: `kept ${kept}, wanted ${wanted} (${said})` }
  }

  return { model, effort, reason: forced ? `${tier}, forced by risk` : `${tier} (${said})` }
}

// --- strategy ---------------------------------------------------------------

export interface StrategyConfig {
  /** How sure the answer must be before anything is attached. */
  minConfidence: number
  /** The higher bar for `graph`, the costliest way to work. */
  minGraphConfidence: number
  /** A skill to name for `graph` (e.g. a heavier orchestration skill); '' for none. */
  graphSkill: string
}

export interface StrategyAdvice {
  /** The block attached to the prompt, or null to attach nothing. */
  block: string | null
  /** Why, for the log line. */
  reason: string
}

const STRATEGY_HOW: Record<Exclude<Strategy, 'direct'>, string> = {
  delegate:
    'Send the broad, mechanical part (searching or reading across many files) to one subagent with a self-contained brief and a request for a short report, then do the rest here. Keep small lookups here: a subagent costs a fresh context.',
  parallel:
    'Fan out, then join. Split the work into independent pieces that share no files, and start one subagent per piece in a single message, in the background, so they run at the same time. Give each a self-contained brief naming its files and how to check its piece. Then join here: read their reports, integrate, and run the tests once. Two pieces that touch the same file are one piece.',
  graph: [
    'Split the work into nodes, one subagent per independent part (a step you could do inline is not a node).',
    'Nodes with no dependency between them start together, in one message, in the background; a dependent wave starts after its inputs join here.',
    'Keep a plan file only if there are more than two waves. After the final join, one read-only reviewer checks the result against the tests; a failed node is redone alone.',
    'At most 4 subagents at a time. If it cannot be explained in one breath, work directly.',
  ].join('\n'),
  junior: [
    'Junior and lead. Hand the coding to the jev-pilot:junior subagent (a cheaper model) with a self-contained brief: the files to change, the exact behavior, and the command that proves it. Do not write the code yourself first.',
    'Then review its work as the note about the crew says.',
  ].join('\n'),
}

/**
 * The advice attached to a prompt about how to carry it out, or no block.
 *
 * Advice is only given when it would change something (`direct` is how the
 * main conversation works anyway), when the answer is confident enough, and
 * when it agrees with the tier: splitting work across subagents is never
 * worth it for a task read as mechanical, and a graph only for a hard one.
 * An unmeasured answer (no confidence) is never acted on: every strategy
 * but `direct` spends more.
 */
export function adviseStrategy(decision: Decision | null, config: StrategyConfig): StrategyAdvice {
  const strategy = decision?.strategy ?? null
  if (!decision || !strategy) return { block: null, reason: 'no strategy answer' }
  if (strategy === 'direct') return { block: null, reason: 'direct' }
  const confidence = decision.strategyConfidence ?? null
  if (confidence === null) return { block: null, reason: `${strategy} without a confidence; not acted on` }
  const bar = strategy === 'graph' ? config.minGraphConfidence : config.minConfidence
  if (confidence < bar) return { block: null, reason: `${strategy} ${confidence.toFixed(2)} < ${bar}` }
  if (strategy === 'graph' && decision.tier !== 'deep') {
    return { block: null, reason: `graph, but tier ${decision.tier}; not acted on` }
  }
  if (strategy === 'parallel' && decision.tier === 'fast') {
    return { block: null, reason: 'parallel, but tier fast; not acted on' }
  }
  // Work that needs the deep tier is not a junior's: design, unclear causes, risk.
  if (strategy === 'junior' && (decision.tier === 'deep' || (decision.risky ?? 0) > 0.5)) {
    return { block: null, reason: `junior, but tier ${decision.tier}${(decision.risky ?? 0) > 0.5 ? ', risky' : ''}; not acted on` }
  }

  const how =
    strategy === 'graph' && config.graphSkill
      ? `${STRATEGY_HOW.graph} If the work warrants its full workflow, the \`${config.graphSkill}\` skill does this; it is heavier and slower, so prefer the plain version above unless the task needs it.`
      : STRATEGY_HOW[strategy]
  const block = [
    '<execution_strategy>',
    `A fast decision model read this request as best carried out as: ${strategy}.`,
    how,
    'It saw only the request and a few recent messages, not the code. If the actual work does not fit, ignore this and work directly.',
    '</execution_strategy>',
  ].join('\n')
  return { block, reason: `${strategy} (${confidence.toFixed(2)})` }
}

// --- telling the model what jev-pilot does ----------------------------------------

/** Which parts of jev-pilot are switched on, for the note to the model. */
export interface Capabilities {
  effort: boolean
  raise: boolean
  subagents: boolean
  subagentEffort: boolean
  skills: boolean
  strategy: boolean
  model: boolean
  /** The quality reads: advice blocks, correction marks, step-back notes. */
  quality?: boolean
}

/**
 * The note the main model gets once per session (and again after a
 * compaction): what jev-pilot decides for it, so it neither fights that (by
 * pinning a subagent's model or effort, or making agent types just to fix an
 * effort) nor tells the user jev-pilot cannot do what it does. Only the parts
 * switched on are named; null when none is.
 */
/**
 * Anthropic's line for low effort (building with Sonnet 5.5): at `low`, a
 * model sometimes skips the check that exercises a change. Given to the main
 * conversation once, and appended to a subagent's brief that runs at low.
 */
export const CHECK_AT_LOW =
  'When you change code that can be run, built, or type-checked, run a real check that exercises the change before reporting it done.'

export function capabilityNote(on: Capabilities, crew: string[] = []): string | null {
  const does: string[] = []
  if (on.effort) {
    does.push(
      on.raise
        ? "- sets this conversation's reasoning effort for each turn (low to xhigh), and raises it a level, up to max, when tool calls keep failing"
        : "- sets this conversation's reasoning effort for each turn (low to xhigh)",
    )
  }
  if (on.model) does.push("- may switch this conversation's model for a turn")
  if (on.subagents) {
    does.push(
      on.subagentEffort
        ? "- sets each subagent's model (haiku, sonnet or opus) and its reasoning effort, from the task in its prompt"
        : "- sets each subagent's model (haiku, sonnet or opus), from the task in its prompt",
    )
  }
  if (on.skills) does.push('- attaches the one skill a request needs, if any')
  if (on.strategy) does.push('- may attach an <execution_strategy> block on how to carry the work out')
  if (on.quality) {
    does.push(
      '- may attach a <jev_quality> block, its read of the request (vague, a bug, a costly area), and add a note after a tool result when a turn goes in circles',
    )
  }
  if (does.length === 0 && crew.length === 0) return null
  const leave: string[] = []
  if (on.subagents) {
    leave.push(
      on.subagentEffort
        ? "Leave subagents' model and effort to it: don't pin them in an Agent tool call (workflow scripts are the exception, see below), and don't create agent types only to fix a model or an effort, unless the user asks; a model you set is kept. Write each subagent's prompt as a clear, self-contained task; that is what it rates."
        : "Leave subagents' model to it: don't pin one in an Agent tool call (workflow scripts are the exception, see below) unless the user asks; a model you set is kept. Write each subagent's prompt as a clear, self-contained task; that is what it rates.",
    )
  }
  if (on.effort) {
    leave.push("Don't change the effort yourself unless the user asks.")
    leave.push(`At low effort too: ${CHECK_AT_LOW.charAt(0).toLowerCase()}${CHECK_AT_LOW.slice(1)}`)
  }
  return [
    '<jev_pilot>',
    ...(does.length > 0 ? ['jev-pilot is running in this session. Before each turn, a fast decision model reads the request and:', ...does] : ['jev-pilot is running in this session.']),
    ...leave,
    ...crew,
    'Its blocks are advice: follow them where they fit the actual code.',
    'The user switches any part on or off with /jev.',
    '</jev_pilot>',
  ].join('\n')
}

// --- escalation within a turn -----------------------------------------------

/** Why the decision model gave no answer: too slow, too busy, or an error. */
export type Miss = 'timeout' | 'busy' | 'error'

/**
 * The miss a response stands for: no response in time (null) is a timeout;
 * 429 (rate limited), 502, 503 and 529 (overloaded) mean the backend is busy
 * and will answer again later; any other status is an error worth showing.
 */
export function missOf(status: number | null): Miss {
  if (status === null) return 'timeout'
  return status === 429 || status === 502 || status === 503 || status === 529 ? 'busy' : 'error'
}

/**
 * Whether a later request of a turn is the engine's own move to another
 * model: it names a model other than the one the engine named for the turn's
 * first request (before any rewrite). That is Claude Code's overload
 * fallback (`--fallback-model`, after repeated 529s), retried as the turn's
 * next request; a routed model must not send it back to the overloaded one.
 * With no first request seen (`first` null), nothing is known to have moved.
 */
export function engineMoved(first: string | null, model: string): boolean {
  return first !== null && model !== first
}

/**
 * The reasoning level to raise a struggling turn to, or null to leave it.
 *
 * Called once `failed` tool calls in a row reach `after`. The trouble itself
 * decides that effort goes up, by at least one rung; the decision model's
 * fresh reading (`score`, null without one) may take it further. Never down,
 * never past the ceiling, and never for a numeric effort, which is the
 * caller's own scale. `config.maxEffort` here is the raise's own ceiling
 * (`maxRaisedEffort`), which may sit above the one a turn starts under.
 */
export function escalate(
  current: string | number | undefined,
  failed: number,
  after: number,
  score: number | null,
  config: { maxEffort?: Effort },
): Effort | null {
  if (after <= 0 || failed < after) return null
  if (typeof current === 'number') return null
  const ceiling = ceilingOf(config)
  // An unset or unknown effort is read as the middle of the ladder.
  const from = effortRank(current) ?? EFFORT_ORDER.indexOf('medium')
  if (from >= ceiling) return null
  const read = score === null ? -1 : EFFORT_ORDER.indexOf(effortLevel(score))
  const to = Math.min(ceiling, Math.max(from + 1, read))
  return EFFORT_ORDER[to] as Effort
}

/**
 * Holds a prompt's classification until the turn that reads that prompt
 * starts.
 *
 * Nothing ties a decision to the turn it belongs to. Prompts can be queued
 * while the model is busy, a peer session's message can be delivered inside a
 * running turn, and `prompt.submit` carries no turn id at all while the
 * session is idle. So when more than one prompt is waiting, `take` reports
 * none: running a turn on another prompt's decision is a worse outcome than
 * not routing it, and not routing is what every other failure path here does.
 */
export function pendingDecisions<T = Decision>(): {
  put(value: T | null): void
  take(): T | null
  /** The prompt last put will not start a turn (refused further down). */
  withdraw(): void
  /** A new session: nothing waiting carries over. */
  clear(): void
} {
  let held: T | null = null
  let waiting = 0

  return {
    put(value) {
      waiting += 1
      // Past the first, which prompt a turn will read is unknowable, so the
      // slot is emptied instead of holding a decision that may not fit.
      held = waiting === 1 ? value : null
    },
    take() {
      const value = waiting === 1 ? held : null
      held = null
      waiting = 0
      return value
    },
    withdraw() {
      // With one waiting, it is the one withdrawn. With more, the slot is
      // already empty and stays so: which one remains is still unknowable.
      waiting = Math.max(0, waiting - 1)
      if (waiting === 0) held = null
    },
    clear() {
      held = null
      waiting = 0
    },
  }
}

/** A number for the log, or `n/d` when the backend reported none. */
function reported(value: number | null): string {
  return value === null ? 'n/d' : value.toFixed(2)
}

/**
 * The one-time line that says the router is alive, which backend answers it,
 * and which of the three switches are on.
 *
 * Without this, a router that loaded and a router that never loaded are told
 * apart only by the absence of later lines, which is not evidence of anything.
 */
export function describeSetup(
  provider: Provider | null,
  url: string,
  switches: { subagentModel: boolean; mainEffort: boolean; mainModel: boolean },
  // `provider: "builtin"` is a choice, not a missing key. Reporting it as a
  // credential problem sends someone hunting for a key they meant to omit.
  builtinByChoice = false,
): string {
  const backend = provider
    ? `${provider} (${url})`
    : builtinByChoice
      ? 'the built-in classifier, by choice'
      : 'the built-in classifier, no key set'
  const on = [
    switches.subagentModel && 'subagent model',
    switches.mainEffort && 'main effort',
    switches.mainModel && 'main model',
  ].filter(Boolean)
  return `ready on ${backend}; routing ${on.length > 0 ? on.join(', ') : 'nothing, every switch is off'}`
}

/**
 * What the decision model answered, before any policy touches it: the raw
 * tier, effort and risk with their confidences, and how long it took.
 *
 * This is the line that shows the classification happened at all, separately
 * from whether the policy then decided to act on it.
 */
export function describeDecision(decision: Decision | null, ms: number | null, margin = 0): string {
  const took = ms === null ? '' : ` · ${Math.round(ms)}ms`
  if (!decision) return `no answer${took}`

  const parts = [`tier ${decision.tier} (${reported(decision.confidence)})`]
  const level = effortScoreOf(decision, margin)
  if (decision.effort !== null && level !== null) {
    parts.push(
      `effort ${decision.effort.toFixed(1)} → ${effortLevel(level)} (${reported(decision.effortConfidence)})`,
    )
  }
  if (decision.risky !== null) parts.push(`risky ${reported(decision.risky)}`)
  if (decision.strategy) parts.push(`strategy ${decision.strategy} (${reported(decision.strategyConfidence ?? null)})`)
  const reads = (['underspecified', 'bugfix', 'sensitive', 'corrects'] as const).filter((name) => typeof decision[name] === 'number')
  if (reads.length > 0) parts.push(reads.map((name) => `${name} ${reported(decision[name] as number)}`).join(' '))
  return parts.join(' · ') + took
}

/**
 * The persistent status line: the last thing the router did, short enough to
 * sit on screen beside the engine's own notices.
 */
export function describeStatus(
  decision: Decision | null,
  change: { model?: string; effort?: Effort } | null,
): string {
  if (!decision) return 'jev · no answer'
  const asked = `${decision.tier} ${reported(decision.confidence)}`
  if (!change) return `jev · ${asked} · unchanged`
  const to = [change.model, change.effort].filter(Boolean).join('/')
  return `jev · ${asked} → ${to}`
}

// --- a turn going in circles --------------------------------------------------------

/** The tools that change a file, counted per file within a turn. */
const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit'])
/** A file edited this many times in one turn, or a command run this many times still failing. */
export const SPIN_EDITS = 4
export const SPIN_RUNS = 3

/**
 * Counts a tool call into the turn's tallies, and says why the turn looks to
 * be going in circles when this call makes it so: the same file edited
 * SPIN_EDITS times, or the same command failing SPIN_RUNS times with no pass
 * between (a pass starts its count again). Null otherwise. Counted locally,
 * from the calls alone.
 */
export function spinOf(
  input: { tool?: string; file_path?: unknown; command?: unknown },
  failed: boolean,
  edits: Map<string, number>,
  runs: Map<string, number>,
): string | null {
  if (input.tool && EDIT_TOOLS.has(input.tool) && typeof input.file_path === 'string') {
    const count = (edits.get(input.file_path) ?? 0) + 1
    edits.set(input.file_path, count)
    if (count === SPIN_EDITS) return `the same file (${input.file_path.split('/').pop()}) was edited ${count} times in this turn`
  }
  if (input.tool === 'Bash' && typeof input.command === 'string') {
    const command = input.command.trim().replace(/\s+/g, ' ')
    if (!failed) {
      runs.delete(command)
      return null
    }
    const count = (runs.get(command) ?? 0) + 1
    runs.set(command, count)
    if (count === SPIN_RUNS) return `the same command (${command.slice(0, 60)}) failed ${count} times in this turn`
  }
  return null
}

/**
 * What the model reads after the tool result that shows the circle. At
 * xhigh or above it also names the next step Anthropic suggests for Opus
 * 5.5: if xhigh hits the same problem twice, Fable 5.1 for that step, then
 * back (a model switch costs a cache write, so it's the user's call).
 */
export function stepBackNote(circle: string, atTop = false): string {
  const note = `[jev-pilot] This turn may be going in circles: ${circle}. Reconsider the cause from the latest error already above; if the last fixes didn't work, try a different approach rather than a variant.`
  return atTop
    ? `${note} This is already at high effort; if it stays stuck, suggest to the user switching to Fable for this step (/model fable, then back with /model once it's solved).`
    : note
}

// --- where changing the effort costs the cache --------------------------------------

/**
 * Whether changing the effort mid-conversation clears the cached
 * conversation. With an API key or a Claude subscription it keeps the cache
 * (on Opus 5.5), so jev-pilot sets the effort per turn for free. On Amazon
 * Bedrock, Google Cloud, or a gateway in front of the API, the effort is part
 * of what the cache matches, and the next request pays the cache-write price
 * on the whole conversation. `upstream` is where Claude requests really go
 * (claude-jev's router passes them on), when that isn't Anthropic's API.
 */
export function effortClearsCache(env: { bedrock?: string; vertex?: string; upstream?: string }): boolean {
  const on = (value: string | undefined) => !!value && !/^(0|false|no|off)?$/i.test(value.trim())
  if (on(env.bedrock) || on(env.vertex)) return true
  const upstream = env.upstream?.trim()
  if (!upstream) return false
  try {
    return new URL(upstream).hostname !== 'api.anthropic.com'
  } catch {
    return false
  }
}

